style.css:
@-moz-document domain("roblox.com") {
/* Dein GIF Hintergrund */
body {
    background: url("https://userstyles.org/style_screenshots/6f33354e85790c01b000b17e600e1bd4.gif") center / cover no-repeat fixed !important;
}

/* ENTFERNT diesen dunklen Overlay */
body::before,
body::after {
    display: none !important;
}

/* Entfernt Pattern / Background Layer von Roblox & RoPro */
[class*="background"],
[class*="container"],
[class*="content"] {
    background: transparent !important;
}
}
